template:
fn name(code: i32) -> &'static str {
    match code {
        200 => "ok",
        404 => ⟦missing⟧,
        ⟦rest⟧ => "other",
    }
}

fn main() {
    println!("{}", name(404));
}

tests:
#[test]
fn names() {
    assert_eq!(name(200), "ok");
    assert_eq!(name(404), "missing");
    assert_eq!(name(500), "other");
    assert_eq!(name(1), "other");
}
